#data for the 2003-2004 sampling season
forspecieseffort_2003_2004 <- c(62, 1, 4, 1, 3, 1, 4, 2, 9, 7, 1, 279, 198, 4, 1, 4, 150, 13, 5, 63, 2, 399, 1, 5, 5, 6, 4, 1, 1, 118, 2)

#iNEXT requires data to be in a named list format
#the names assigned to the list items (e.g., '2023') will appear in your plots as legends
critters <- list(
  'BLI'=BLI,
  'LAK'=LAK,
  'LDF'=LDF,
  'NEB'=NEB,
  'CLE'=CLE,
  'DFL'=DFL,
  'PBC'=PBC,
  'HCS'=HCS,
  'HCN'=HCN,
  'SHE'=SHE)

critters_in <- iNEXT(critters, q = c(2), datatype = 'abundance', endpoint = 4500)
#q = is what type of diversity, 0 is species richness, 1 is shannon diversity, 2 is simpson diversity
#the way i did it calculates all 3
#the datatype should be changed to 'incidence' if using presence/absence data
#endpoint is saying the number of individuals to extrapolate to, you can change this for your own purposes
library(iNEXT)
library(ggplot2)
big_theme <- theme(
  axis.text = element_text(size = 14, color = "black"),
  axis.title = element_text(size = 16, color = "black"),
  strip.text = element_text(size = 15),     # Labels for the different diversity orders (q)
  legend.text = element_text(size = 13),
  legend.title = element_text(size = 14),
  plot.title = element_text(size = 18, hjust = 0.5)
)
#you don't have to use this, it's for plotting purposes to make all the font sizes bigger idk

#species accumulation curve plot.  CHANGED facet.var = "Order.q" to "None"
ggiNEXT(critters_in, type=1, se=TRUE, facet.var="None", color.var="Assemblage", grey=FALSE) +
  facet_wrap(~Order.q, scales="free") +
  theme_bw() +
  big_theme +
  theme(legend.position = "bottom", legend.box = "vertical") +
  coord_cartesian(ylim = c(0, 30))
  #coord_cartesian(xlim = c(0,5300))
#facet.var="Order.q" creates separate panels for q=0, q=1, and q=2
#coord_cartesian allows you to zoom in/out the axes, xlim and ylim accept vectors with the limits you want
#on both axes

#species coverage curve based on indiv
ggiNEXT(critters_in, type=2, se=TRUE, facet.var="None", color.var="Assemblage", grey=FALSE) +
  theme_bw() +
  big_theme +
  theme(legend.position = "bottom", legend.box = "vertical") +
  coord_cartesian(ylim = c(0, 1.25), xlim = c(0, 225))

#sample coverage curves.  CHANGED Order.q to None
ggiNEXT(critters_in, type=3, se=TRUE, facet.var = "None", color.var="Assemblage", grey=FALSE) +
  facet_wrap(~Order.q, scales="free") +
  theme_bw() +
  theme(legend.position = "bottom", legend.box = "vertical") +
  coord_cartesian(ylim = c(0, 30), xlim = c(0,1))

